use vstd::prelude::*;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int| 0 <= i < m.len() ==> result[i] == m[m.len() - 1 - i],
{
    let n: usize = m.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            result.len() == i,
            forall|k: int| 0 <= k < i ==> result[k] == m[n - 1 - k],
        decreases n - i,
    {
        // Push m[n-1-i] to become result[i]
        result.push(m[n - 1 - i]);

        // After push: new last element is at index i.
        assert(result.len() == i + 1);
        assert(result[i as int] == m[n - 1 - i]);

        i += 1;
    }

    result
}

} // verus!